.darma-loader-tw-table-skeleton { display: flex; flex-direction: column; gap: calc(var(--loader-size, 190px) * .05); width: var(--loader-size, 190px); }
.darma-loader-tw-table-skeleton .darma-loader-tw-table-skeleton__row { display: flex; gap: calc(var(--loader-size, 190px) * .04); }
.darma-loader-tw-table-skeleton .darma-loader-tw-table-skeleton__row i { flex: 1; height: calc(var(--loader-size, 190px) * .06); border-radius: calc(var(--loader-size, 190px) * .015); background: color-mix(in srgb, var(--loader-color, #94a3b8) 30%, transparent); animation: darma-loader-tw-table-skeleton-twCell calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-tw-table-skeleton .darma-loader-tw-table-skeleton__row i:first-child { flex: .45; }
.darma-loader-tw-table-skeleton .darma-loader-tw-table-skeleton__row:nth-child(2) i { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-tw-table-skeleton .darma-loader-tw-table-skeleton__row:nth-child(3) i { animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-tw-table-skeleton-twCell { 0%, 100% { opacity: .3; } 50% { opacity: 1; } }

